__NUXT_JSONP__("/por/about", (function(a){return {data:[{details:{slug:"por",pageTitle:"O que é MLI? | Mentor Language Institute",pageDescription:"Mentor Language Institute foi fundada em 2002 e está localizada em duas áreas populares: Westwood e Hollywood.",section1:{title:"O que é MLI?",description:["Mentor Language Institute foi fundada em 2002 e está localizada em duas áreas populares: Westwood e Hollywood.\u003Cbr \u002F\u003EAjudamos estudantes de todo o mundo a melhorar o inglês.."]},section2:{image:"\u002Fimages\u002Fwhat-is-mli\u002Fabout\u002Fpay-less-for-quality-classes.jpg",title:"Pague menos por aulas de qualidade",description:["Valorizamos duas coisas:  \u003Cb\u003E\"Educação de Qualidade\"\u003C\u002Fb\u003E e \u003Cb\u003E\"Preço\".\u003Cb\u003E","O inglês é a língua global e uma ferramenta necessária para a comunicação com as pessoas de todo o mundo. Nossa esperança é que os estudantes internacionais adquirem habilidades de inglês para ter sucesso no mundo. Por esta razão, nos concentramos na qualidade das aulas e preço baixo."]},section3:{image:"\u002Fimages\u002Fwhat-is-mli\u002Fabout\u002Fmli-staff.jpg",title:"Até 2020, mais de 17.000 estudantes escolheram e se formaram na MLI.",description:["Oferecemos ESL (Programa de inglês geral com 6 áreas de habilidades: Gramática \u002FEscrita, Leitura\u002FVocabulário e Escuta\u002FFala), TOEFL®, IELTS ™ (Para alunos que desejam transferir para a faculdade) e TOEIC®.","Muitos estudantes também passaram a estudar em universidades ou faculdades nos EUA como UCLA, USC e Santa Monica College."],lists:[{link:"\u002Fpor\u002Ffeature",image:a,text:"5 razões pelas quais as pessoas escolhem MLI"},{link:"\u002Fpor\u002Fcompany",image:a,text:"Informações da Empresa"},{link:"\u002Fpor\u002Fimage-gallery",image:a,text:"Galeria de fotos\u002Fvídeos"}]},dir:"\u002Fabout",path:"\u002Fabout\u002Fpor",extension:".json",createdAt:"2026-10-22T16:31:28.454Z",updatedAt:"2025-05-26T12:06:27.574Z"}}],fetch:{},mutations:void 0}}("\u002Fimages\u002Ficons\u002Fboxed-arrow.svg")));